ee:variables.ee:set-variable:
%dw 2.0
output application/json
---
{
	ConnectionNumber: vars.initialPayload.ticket.service.connectionNumber
}

%dw 2.0
output application/json
var serviceTechnology = vars.serviceResponse.servicios[0].Bundle.Tipo_Servicio
var serviceActiveTechnology = vars.serviceResponse.services[0].Tecnologia
---
if(serviceTechnology != null)
vars.initialPayload  update {
    case botFailure  at .ticket.pqr.failure.botRequest -> botFailure ++ " " ++ serviceTechnology
}
else if (serviceActiveTechnology != null)
vars.initialPayload  update {
    case botFailure  at .ticket.pqr.failure.botRequest -> botFailure ++ " " ++ serviceActiveTechnology
}
else vars.initialPayload

%dw 2.0
output application/json
var serviceTechnology = vars.serviceResponse.servicios
var serviceActiveTechnology = vars.serviceResponse.services
---
if(not isEmpty(serviceTechnology))

{
	Numero_Documento: serviceTechnology[0].Cliente.Numero_Documento,
	Tipo_Documento: serviceTechnology[0].Cliente.Tipo_Documento
}
else if(not isEmpty(serviceActiveTechnology))
{
	Numero_Documento: serviceActiveTechnology[0].Numero_Identificacion,
	Tipo_Documento: serviceActiveTechnology[0].Tipo_Documento
}
else {
	Numero_Documento: vars.initialPayload.ticket.customer.documentNumber,
	Tipo_Documento: vars.initialPayload.ticket.customer.documentType
}

%dw 2.0
output application/json
var serviceTechnology = vars.serviceResponse.servicios
var serviceActiveTechnology = vars.serviceResponse.services
var serviceOwner = if(serviceTechnology != [])
{
	documentNumber: serviceTechnology[0].Cliente.Numero_Documento,
	documentType: serviceTechnology[0].Cliente.Tipo_Documento
}
else if(serviceActiveTechnology != [])
{
	documentNumber: serviceActiveTechnology[0].Numero_Identificacion,
	documentType: serviceActiveTechnology[0].Tipo_Documento
}else {
	documentNumber: "",
	documentType: ""
}
---
serviceOwner == {
	documentNumber: vars.initialPayload.ticket.customer.documentNumber,
	documentType: vars.initialPayload.ticket.customer.documentType
}

%dw 2.0
output application/json
var requestPqr = vars.initialPayload.ticket.pqr.failure
var matchPqr = vars.pqrDuplicateResponse.pqrDuplicate filter ((item, index) -> lower(item.estado_pqr) == "abierta" and item.causal_pqr == requestPqr.causal and item.clase_pqr == requestPqr.class and item.motivo_pqr == requestPqr.reason and item.sintoma_pqr == requestPqr.symptom)
---
{
	duplicate: isEmpty(matchPqr),
	cun: matchPqr[0].cun default 0
}

ee:message.ee:set-payload:
%dw 2.0
import * from dw::core::Binaries
output multipart/form-data
var attachments = vars.initialPayload.ticket.pqr.attachment
---
{
	parts: {
		(attachments map (item, index) -> {
			attachmentId: {
				content: item.id
			},
			files: {
				content: fromBase64(item.file),
				headers: {
					"Content-Type": item.mimeType,
					"Content-Disposition": {
						"name": "files",
						"filename": item.name
					}
				}
			}
		})
	}
}
